def mincostToHireWorkers(quality: list[int], wage: list[int], k: int) -> float:
    import heapq
    workers = sorted([(w / q, q) for w, q in zip(wage, quality)])
    max_heap = []
    q_sum = 0
    min_cost = float('inf')
    for ratio, q in workers:
        heapq.heappush(max_heap, -q)
        q_sum += q
        if len(max_heap) > k:
            q_sum += heapq.heappop(max_heap)
        if len(max_heap) == k:
            min_cost = min(min_cost, ratio * q_sum)
    return round(min_cost, 5)

